    const std::int32_t y = action->y + offsetY;
    const std::int32_t x = action->x + offsetX;
    fields.clip = 0;
    descriptor = ToGraphicDescriptor(fields);
    return DrawGraphic(x, y, 0xCF, 0x3BDEE, 0, &descriptor);
